  private async fetchCompanyUsersWithCalendarStatus(
    companyId: number,
    roles: Array<'admin' | 'agent'>
  ): Promise<Array<{ userId: number; fullName: string; email: string; avatarUrl: string | null; role: string; calendarSettings: AgentCalendarSettings | null; isCalendarConnected: boolean }>> {
    type AgentCalendarRow = { userId: number; fullName: string; email: string; avatarUrl: string | null; role: string; tokenUserId: number | null };
    const rows = await db
      .select({
        userId: users.id,
        fullName: users.fullName,
        email: users.email,
        avatarUrl: users.avatarUrl,
        role: users.role,
        tokenUserId: googleCalendarTokens.userId
      })
      .from(users)
      .leftJoin(
        googleCalendarTokens,
        and(
          eq(googleCalendarTokens.userId, users.id),
          eq(googleCalendarTokens.companyId, companyId)
        )
      )
      .where(
        and(
          eq(users.companyId, companyId),
          inArray(users.role, roles)
        )
      ) as AgentCalendarRow[];

    const settings = await this.getAllAgentCalendarSettings(companyId);

    const settingsByUserId = new Map<number, AgentCalendarSettings>();
    for (const setting of settings) {
      settingsByUserId.set(setting.userId, setting);
    }

    return rows.map((row) => {
      const calendarSettings = settingsByUserId.get(row.userId) || null;
      const isCalendarConnected = !!row.tokenUserId;

      return {
        userId: row.userId,
        fullName: row.fullName,
        email: row.email,
        avatarUrl: row.avatarUrl,
        role: row.role,
        calendarSettings,
        isCalendarConnected
      };
    });
  }

