  /**
   * Create a confirmed calendar booking record
   * @param bookingData Booking data including userId, companyId, calendarType, startDateTime, endDateTime, and optional eventId and eventLink
   * @returns Success status with bookingId or error message
   */
  async createCalendarBooking(bookingData: { userId: number; companyId: number; calendarType: string; calendarId?: string; startDateTime: Date; endDateTime: Date; bufferStartDateTime?: Date; bufferEndDateTime?: Date; bufferMinutes?: number; eventId?: string; eventLink?: string; status?: 'pending' | 'confirmed' | 'cancelled' | 'orphaned'; idempotencyKey?: string; etag?: string }): Promise<{ success: boolean; bookingId?: number; booking?: CalendarBooking; error?: string }> {
    try {
      const [booking] = await db.transaction(async (tx: any) => {
        return tx
          .insert(calendarBookings)
          .values({
            userId: bookingData.userId,
            companyId: bookingData.companyId,
            calendarType: bookingData.calendarType,
            calendarId: bookingData.calendarId || 'primary',
            startDateTime: bookingData.startDateTime,
            endDateTime: bookingData.endDateTime,
            bufferStartDateTime: bookingData.bufferStartDateTime || bookingData.startDateTime,
            bufferEndDateTime: bookingData.bufferEndDateTime || bookingData.endDateTime,
            bufferMinutes: bookingData.bufferMinutes || 0,
            eventId: bookingData.eventId || null,
            eventLink: bookingData.eventLink || null,
            status: bookingData.status || 'confirmed',
            idempotencyKey: bookingData.idempotencyKey || null,
            etag: bookingData.etag || null
          })
          .returning();
      });

      if (booking) {
        return { success: true, bookingId: booking.id, booking };
      } else {
        return { success: false, error: 'Booking already exists or conflict detected' };
      }
    } catch (error: any) {
      if (error.code === '23P01') {
        return { success: false, error: 'overlapping_booking' };
      }
      // Check for unique constraint violation (PostgreSQL error code 23505)
      if (error.code === '23505' || error.message?.includes('unique constraint') || error.message?.includes('duplicate key')) {
        if (bookingData.idempotencyKey) {
          const existing = await this.getCalendarBookingByIdempotencyKey(
            bookingData.userId,
            bookingData.companyId,
            bookingData.calendarType,
            bookingData.calendarId,
            bookingData.idempotencyKey
          );
          return {
            success: false,
            bookingId: existing?.id,
            booking: existing || undefined,
            error: 'idempotency_key_conflict'
          };
        }
        return { success: false, error: 'Time slot is already booked' };
      }
      
      console.error('Error creating calendar booking:', error);
      return { success: false, error: error.message || 'Failed to create booking' };
    }
  }

