  async pruneExpiredSlotLocks(): Promise<number> {
    try {
      const deleted = await db
        .delete(calendarSlotLocks)
        .where(lt(calendarSlotLocks.expiresAt, new Date()))
        .returning({ id: calendarSlotLocks.id });
      return deleted.length;
    } catch (error) {
      console.error('Error pruning expired calendar slot locks:', error);
      return 0;
    }
  }

