  async createChannelConnection(connection: InsertChannelConnection): Promise<ChannelConnection> {

    const connectionData = { ...connection };
    if (connectionData.channelType === 'messenger') {
      connectionData.status = 'active';
    }

    if (connectionData.channelType === 'tiktok') {
      const enc = encryptTikTokChannelConnectionForWrite(
        connectionData as Pick<ChannelConnection, 'channelType' | 'accessToken' | 'connectionData'>
      );
      (connectionData as any).accessToken = enc.accessToken;
      (connectionData as any).connectionData = enc.connectionData;
    }

    const [newConnection] = await db.insert(channelConnections).values(connectionData).returning();
    return newConnection;
  }

