  async updateChannelConnection(id: number, updates: Partial<InsertChannelConnection>): Promise<ChannelConnection> {
    let payload: Partial<InsertChannelConnection> = { ...updates };
    if (updates.accessToken !== undefined || updates.connectionData !== undefined) {
      const [existing] = await db
        .select()
        .from(channelConnections)
        .where(eq(channelConnections.id, id))
        .limit(1);
      if (existing?.channelType === 'tiktok') {
        const enc = encryptTikTokChannelConnectionForWrite({
          channelType: 'tiktok',
          accessToken:
            updates.accessToken !== undefined ? updates.accessToken : existing.accessToken,
          connectionData:
            updates.connectionData !== undefined ? updates.connectionData : existing.connectionData,
        });
        payload = {
          ...payload,
          accessToken: enc.accessToken ?? undefined,
          connectionData: enc.connectionData as InsertChannelConnection['connectionData'],
        };
      }
    }

    const [updatedConnection] = await db
      .update(channelConnections)
      .set({ ...payload, updatedAt: new Date() })
      .where(eq(channelConnections.id, id))
      .returning();
    return updatedConnection;
  }

