  async createConversation(conversation: InsertConversation): Promise<Conversation> {
    const newConversation = conversation.channelType === 'instagram' ? await getDb().transaction(async tx => {
      await tx.execute(sql`SELECT pg_advisory_xact_lock(hashtext(${`instagram-conversation:${conversation.companyId}:${conversation.channelId}:${conversation.contactId}`}))`);
      const [existing] = await tx.select().from(conversations).where(and(eq(conversations.channelId, conversation.channelId),
        eq(conversations.contactId, conversation.contactId!), eq(conversations.companyId, conversation.companyId!))).limit(1);
      return existing ?? (await tx.insert(conversations).values(conversation).returning())[0];
    }) : (await db.insert(conversations).values(conversation).returning())[0];
    import('./services/conversation-metrics-service').then(m =>
      m.default.initMetric(
        newConversation.id,
        newConversation.companyId,
        newConversation.channelType,
        newConversation.createdAt ?? new Date()
      ).catch(e => console.error('[metrics] initMetric failed:', e))
    );
    return newConversation;
  }

