  async getLatestMessageForConversations(conversationIds: number[]): Promise<Record<number, Message>> {
    const out: Record<number, Message> = {};
    if (!conversationIds.length) {
      return out;
    }
    await Promise.all(
      conversationIds.map(async (cid) => {
        const rows = await this.getMessagesByConversationPaginated(cid, 1, 0);
        if (rows[0]) {
          out[cid] = rows[0];
        }
      })
    );
    return out;
  }

