  async getWhatsAppMessageByKey(
    key: { id: string; remoteJid: string; fromMe?: boolean | null; participant?: string | null },
    companyId: number,
  ): Promise<Message | undefined> {
    const candidates = await db
      .select({ message: messages })
      .from(messages)
      .innerJoin(conversations, eq(messages.conversationId, conversations.id))
      .where(and(eq(messages.externalId, key.id), eq(conversations.companyId, companyId)));

    return candidates.map((row: { message: Message }) => row.message).find((message: Message) => {
      if (!message.metadata) return false;
      try {
        const metadata = typeof message.metadata === 'string'
          ? JSON.parse(message.metadata)
          : message.metadata as any;
        const storedKey = metadata?.whatsappMessage?.key || {};
        const remoteMatches = [
          storedKey.remoteJid,
          metadata?.remoteJid,
          metadata?.normalizedRemoteJid,
          metadata?.originalRemoteJid,
          metadata?.groupJid,
        ].includes(key.remoteJid);
        if (!remoteMatches) return false;
        if (typeof key.fromMe === 'boolean') {
          const storedFromMe = typeof storedKey.fromMe === 'boolean'
            ? storedKey.fromMe
            : metadata?.fromMe;
          if (storedFromMe !== key.fromMe) return false;
        }
        if (key.participant) {
          const storedParticipant = storedKey.participant || metadata?.participantJid;
          if (storedParticipant !== key.participant) return false;
        }
        return true;
      } catch {
        return false;
      }
    });
  }

