  async createInstagramMessage(message: InsertMessage): Promise<InstagramMessageResult> {
    let outcome: InstagramMessageResult | undefined;
    await this.createMessage(message, result => { outcome = result; });
    if (!outcome) throw new Error('Instagram message requires an Instagram conversation and provider message ID');
    return outcome;
  }

  async createMessage(message: InsertMessage, observeInstagramResult?: (result: InstagramMessageResult) => void): Promise<Message> {
    try {
      const instagramResult = await persistInstagramMessage(db, message);
      if (observeInstagramResult && !instagramResult) throw new Error('Invalid Instagram message identity');
      if (instagramResult) observeInstagramResult?.(instagramResult);
      const newMessage = instagramResult?.message ?? (await db.insert(messages).values(message).returning())[0];
      if (instagramResult && !instagramResult.created && !instagramResult.attributionUpdated) return newMessage;

      if (!instagramResult) await db
        .update(conversations)
        .set({
          lastMessageAt: new Date(),
          updatedAt: new Date()
        })
        .where(eq(conversations.id, message.conversationId));

      if (!instagramResult && message.direction === 'inbound' && !message.isFromBot) {
        await this.updateConversationUnreadCount(message.conversationId);
      }

      if (!instagramResult || instagramResult.created) import('./services/conversation-metrics-service').then(m =>
        m.default.incrementMessageCounts(
          newMessage.conversationId,
          newMessage.direction === 'outbound' && newMessage.isFromBot === false && newMessage.senderType === 'user'
        ).catch(e => console.error('[metrics] incrementMessageCounts failed:', e))
      );
      if (instagramResult?.attributionUpdated && newMessage.isFromBot === false && newMessage.senderType === 'user') {
        db.update(conversationMetrics).set({ agentMessages: sql`${conversationMetrics.agentMessages} + 1` })
          .where(eq(conversationMetrics.conversationId, newMessage.conversationId))
          .catch((e: unknown) => console.error('[metrics] Instagram agent attribution update failed:', e));
      }

      // Auto-pause bot replies when an owner/agent replies to a contact.
      if (newMessage.direction === 'outbound' && newMessage.isFromBot === false && newMessage.senderType === 'user') {
        try {
          const { resetBotLoopProtectionAfterHumanReply } = await import('./services/bot-loop-protection-service');
          const loopProtectionReset = await resetBotLoopProtectionAfterHumanReply(newMessage.conversationId);
          const [conversation] = await db
            .select({
              id: conversations.id,
              companyId: conversations.companyId,
              contactId: conversations.contactId
            })
            .from(conversations)
            .where(eq(conversations.id, newMessage.conversationId))
            .limit(1);

          if (loopProtectionReset && conversation?.companyId && (global as any).broadcastToAllClients) {
            (global as any).broadcastToAllClients({
              type: 'conversationBotStatusUpdated',
              data: {
                conversationId: newMessage.conversationId,
                botDisabled: false,
                disabledAt: null,
                disableDuration: null,
                disableReason: null,
              },
            }, conversation.companyId);
          }

          if (conversation?.companyId && conversation?.contactId) {
            const enabledSetting = await this.getCompanySetting(conversation.companyId, 'bot_auto_pause_on_owner_reply_enabled');
            const isEnabled = enabledSetting?.value !== undefined ? Boolean(enabledSetting.value) : true;

            if (isEnabled) {
              const durationSetting = await this.getCompanySetting(conversation.companyId, 'bot_auto_pause_duration_minutes');
              const rawDuration = Number(durationSetting?.value);
              const durationMinutes = Number.isFinite(rawDuration) && rawDuration >= 1 && rawDuration <= 1440
                ? Math.floor(rawDuration)
                : 3;

              const suppressedUntil = new Date(Date.now() + durationMinutes * 60 * 1000);
              await this.upsertContactBotSuppression({
                companyId: conversation.companyId,
                contactId: conversation.contactId,
                suppressedUntil,
                reason: 'owner_reply_auto_pause',
                createdBy: newMessage.senderId ?? null
              });
            }
          }
        } catch (suppressionError) {
          console.error('Failed to auto-pause bot after owner reply:', suppressionError);
        }
      }

      return newMessage;
    } catch (error: any) {



      throw error;
    }
  }

