  async getAccessibleFlows(user: Pick<User, 'id' | 'companyId' | 'isSuperAdmin'>): Promise<Flow[]> {
    if (user.isSuperAdmin) {
      return db
        .select()
        .from(flows)
        .orderBy(desc(flows.updatedAt));
    }

    const accessConditions: SQL[] = [
      and(isNull(flows.companyId), eq(flows.userId, user.id))!,
    ];
    if (user.companyId != null) {
      accessConditions.unshift(eq(flows.companyId, user.companyId));
    }

    return db
      .select()
      .from(flows)
      .where(or(...accessConditions))
      .orderBy(desc(flows.updatedAt));
  }

