  async createFlow(flow: InsertFlow): Promise<Flow> {
    const [newFlow] = await db.insert(flows).values(flow).returning();
    const { invalidateNodeCredentialCache } = await import('./services/node-config-cache');
    invalidateNodeCredentialCache(newFlow.companyId);
    return newFlow;
  }

  async updateFlow(id: number, updates: Partial<InsertFlow>): Promise<Flow> {
    const currentFlow = await this.getFlow(id);
    if (!currentFlow) {
      throw new Error(`Flow with id ${id} not found`);
    }

    const [updatedFlow] = await db
      .update(flows)
      .set({
        ...updates,
        updatedAt: new Date(),
        version: currentFlow.version + 1
      })
      .where(eq(flows.id, id))
      .returning();

    const { invalidateNodeCredentialCache } = await import('./services/node-config-cache');
    invalidateNodeCredentialCache(updatedFlow.companyId);

    return updatedFlow;
  }

  async deleteFlow(id: number): Promise<boolean> {
    try {
      return await db.transaction(async (tx: any) => {
        // Lock the parent before cleanup so new FK references cannot race deletion.
        const [flow] = await tx.select({ id: flows.id }).from(flows)
          .where(eq(flows.id, id)).for('update');
        if (!flow) return false;

        const sessionIds = tx.select({ sessionId: flowSessions.sessionId }).from(flowSessions)
          .where(eq(flowSessions.flowId, id));
        const executionIds = tx.select({ id: flowExecutions.id }).from(flowExecutions)
          .where(eq(flowExecutions.flowId, id));
        const scheduleIds = tx.select({ scheduleId: followUpSchedules.scheduleId }).from(followUpSchedules)
          .where(eq(followUpSchedules.flowId, id));

        // Explicit cleanup supports existing databases with non-cascading foreign keys.
        // Logs can reference a flow without referencing a webhook trigger.
        await tx.delete(webhookTriggerLogs).where(eq(webhookTriggerLogs.flowId, id));
        await tx.delete(webhookTriggers).where(eq(webhookTriggers.flowId, id));
        await tx.delete(followUpExecutionLog).where(inArray(followUpExecutionLog.scheduleId, scheduleIds));
        await tx.delete(followUpSchedules).where(eq(followUpSchedules.flowId, id));
        await tx.delete(flowStepExecutions).where(or(
          inArray(flowStepExecutions.flowExecutionId, executionIds),
          inArray(flowStepExecutions.sessionId, sessionIds)
        ));
        await tx.delete(flowExecutions).where(eq(flowExecutions.flowId, id));
        await tx.delete(flowSessionVariables).where(inArray(flowSessionVariables.sessionId, sessionIds));
        await tx.delete(flowSessionCursors).where(inArray(flowSessionCursors.sessionId, sessionIds));
        await tx.delete(flowSessions).where(eq(flowSessions.flowId, id));
        await tx.delete(flowAssignments).where(eq(flowAssignments.flowId, id));
        // Calls are conversation history and must survive deletion of their source flow.
        await tx.update(calls).set({ flowId: null }).where(eq(calls.flowId, id));
        await tx.delete(flows).where(eq(flows.id, id));
        return true;
      });
    } catch (error) {
      console.error('Error deleting flow:', error);
      return false;
    }
  }

