  async cancelFollowUpSchedule(scheduleId: string) {
    try {
      return await db.update(followUpSchedules)
        .set({
          status: 'cancelled',
          processingLeaseExpiresAt: null,
          processingClaimId: null,
          dispatchStartedAt: null,
          updatedAt: new Date()
        })
        .where(
          and(
            eq(followUpSchedules.scheduleId, scheduleId),
            or(
              eq(followUpSchedules.status, 'scheduled'),
              and(eq(followUpSchedules.status, 'processing'), isNull(followUpSchedules.dispatchStartedAt))
            )
          )
        )
        .returning();
    } catch (error) {
      console.error('Error cancelling follow-up schedule:', error);
      throw error;
    }
  }

  /**
   * Mark a claimed follow-up as actively dispatching (outbound call imminent). Not cancellable after this.
   */
  async beginFollowUpDispatch(scheduleId: string, claimId: string) {
    try {
      return await db
        .update(followUpSchedules)
        .set({
          dispatchStartedAt: new Date(),
          updatedAt: new Date()
        })
        .where(
          and(
            eq(followUpSchedules.scheduleId, scheduleId),
            eq(followUpSchedules.processingClaimId, claimId),
            eq(followUpSchedules.status, 'processing'),
            isNull(followUpSchedules.dispatchStartedAt)
          )
        )
        .returning();
    } catch (error) {
      console.error('Error beginning follow-up dispatch:', error);
      throw error;
    }
  }

  /**
   * Compare-and-swap: set sent only if the row still matches this lease and dispatch has started.
   */
  async completeFollowUpAsSent(scheduleId: string, claimId: string) {
    try {
      return await db
        .update(followUpSchedules)
        .set({
          status: 'sent',
          sentAt: new Date(),
          processingLeaseExpiresAt: null,
          processingClaimId: null,
          dispatchStartedAt: null,
          updatedAt: new Date()
        })
        .where(
          and(
            eq(followUpSchedules.scheduleId, scheduleId),
            eq(followUpSchedules.processingClaimId, claimId),
            eq(followUpSchedules.status, 'processing'),
            isNotNull(followUpSchedules.dispatchStartedAt)
          )
        )
        .returning();
    } catch (error) {
      console.error('Error completing follow-up as sent:', error);
      throw error;
    }
  }

