  async getActiveFollowUpsByConversation(conversationId: number, includeMonitored?: boolean) {
    try {
      if (includeMonitored === true) {
        return await db.select()
          .from(followUpSchedules)
          .where(and(
            eq(followUpSchedules.conversationId, conversationId),
            eq(followUpSchedules.cancelOnUserResponse, true),
            or(
              and(
                eq(followUpSchedules.status, 'scheduled'),
                sql`${followUpSchedules.scheduledFor} > NOW()`
              ),
              eq(followUpSchedules.status, 'processing')
            )
          ))
          .orderBy(asc(followUpSchedules.scheduledFor));
      }
      return await db.select()
        .from(followUpSchedules)
        .where(and(
          eq(followUpSchedules.conversationId, conversationId),
          eq(followUpSchedules.status, 'scheduled'),
          sql`${followUpSchedules.scheduledFor} > NOW()`
        ))
        .orderBy(asc(followUpSchedules.scheduledFor));
    } catch (error) {
      console.error('Error getting active follow-ups by conversation:', error);
      return [];
    }
  }

  async cancelFollowUpsByCondition(conversationId: number, condition: 'any_message' | 'specific_topic', metadata?: Record<string, unknown>) {
    try {
      const active = await this.getActiveFollowUpsByConversation(conversationId, true);
      const matching = active.filter(
        (row: Record<string, unknown>) =>
          row.cancelOnUserResponse === true && row.cancelCondition === condition
      );
      let cancelled = 0;
      for (const row of matching) {
        const scheduleId = row.scheduleId as string;
        const rows = await this.cancelFollowUpSchedule(scheduleId);
        if (!Array.isArray(rows) || rows.length === 0) {
          continue;
        }
        cancelled += 1;
        try {
          await this.createFollowUpExecutionLog({
            scheduleId,
            executionAttempt: 1,
            status: 'failed',
            errorMessage: `Cancelled by condition: ${condition}`,
            executedAt: new Date(),
            ...(metadata && Object.keys(metadata).length > 0 ? { responseContent: JSON.stringify(metadata) } : {})
          });
        } catch {
          // optional log; ignore
        }
      }
      return cancelled;
    } catch (error) {
      console.error('Error cancelling follow-ups by condition:', error);
      return 0;
    }
  }

