  /**
   * Save an app setting to the database.
   * 
   * Auth Background Settings:
   * - branding_admin_auth_background: string (image URL) - Admin authentication page background image
   * - branding_user_auth_background: string (image URL) - User authentication page background image
   * - auth_background_config: JSON object - Configuration for auth backgrounds including:
   *   - adminAuthBackground: { backgroundColor?, gradientConfig?, priority: 'image'|'color'|'layer' }
   *   - userAuthBackground: { backgroundColor?, gradientConfig?, priority: 'image'|'color'|'layer' }
   */
  async saveAppSetting(key: string, value: unknown): Promise<AppSetting> {
    try {
      if (!key) {
        throw new Error('Setting key is required');
      }

      if (value === undefined || value === null) {
        throw new Error('Setting value is required');
      }

      const existingSetting = await this.getAppSetting(key);

      if (existingSetting) {
        const [updatedSetting] = await db
          .update(appSettings)
          .set({
            value,
            updatedAt: new Date()
          })
          .where(eq(appSettings.key, key))
          .returning();

        if (!updatedSetting) {
          throw new Error(`Failed to update setting with key ${key}`);
        }

        return updatedSetting;
      } else {
        const [newSetting] = await db
          .insert(appSettings)
          .values({
            key,
            value
          })
          .returning();

        if (!newSetting) {
          throw new Error(`Failed to create setting with key ${key}`);
        }

        return newSetting;
      }
    } catch (error) {
      console.error(`Error saving app setting with key ${key}:`, error);
      throw error;
    }
  }

  async deleteAppSetting(key: string): Promise<boolean> {
    try {
      await db
        .delete(appSettings)
        .where(eq(appSettings.key, key));

      return true;
    } catch (error) {
      console.error(`Error deleting app setting with key ${key}:`, error);
      return false;
    }
  }

  // Email verification token methods
  async createEmailVerificationToken(data: InsertEmailVerificationToken): Promise<EmailVerificationToken> {
    try {
      const [token] = await db
        .insert(emailVerificationTokens)
        .values(data)
        .returning();

      if (!token) {
        throw new Error('Failed to create email verification token');
      }

      return token;
    } catch (error) {
      console.error('Error creating email verification token:', error);
      throw error;
    }
  }

  async getEmailVerificationToken(email: string, token: string): Promise<EmailVerificationToken | undefined> {
    try {
      const [verificationToken] = await db
        .select()
        .from(emailVerificationTokens)
        .where(
          and(
            eq(emailVerificationTokens.email, email),
            eq(emailVerificationTokens.token, token),
            eq(emailVerificationTokens.verified, false),
            gt(emailVerificationTokens.expiresAt, new Date())
          )
        )
        .limit(1);

      return verificationToken;
    } catch (error) {
      console.error('Error getting email verification token:', error);
      return undefined;
    }
  }

  async verifyEmailToken(email: string, token: string): Promise<boolean> {
    try {
      // Atomic UPDATE: only succeeds if the token is still unverified and not expired.
      // This prevents TOCTOU race conditions where concurrent requests could each
      // read verified=false before either write completes.
      const [updated] = await db
        .update(emailVerificationTokens)
        .set({
          verified: true,
          verifiedAt: new Date(),
          updatedAt: new Date()
        })
        .where(
          and(
            eq(emailVerificationTokens.email, email),
            eq(emailVerificationTokens.token, token),
            eq(emailVerificationTokens.verified, false),
            gt(emailVerificationTokens.expiresAt, new Date())
          )
        )
        .returning();

      return !!updated;
    } catch (error) {
      console.error('Error verifying email token:', error);
      return false;
    }
  }

  async invalidatePendingEmailVerificationTokens(email: string): Promise<number> {
    try {
      const result = await db
        .update(emailVerificationTokens)
        .set({ verified: true, updatedAt: new Date() }) // mark as used so they can't be replayed
        .where(
          and(
            eq(emailVerificationTokens.email, email),
            eq(emailVerificationTokens.verified, false),
            gt(emailVerificationTokens.expiresAt, new Date())
          )
        );
      return result.rowCount ?? 0;
    } catch (error) {
      console.error('Error invalidating pending email verification tokens:', error);
      return 0;
    }
  }

  async deleteExpiredEmailVerificationTokens(): Promise<number> {
    try {
      const result = await db
        .delete(emailVerificationTokens)
        .where(lt(emailVerificationTokens.expiresAt, new Date()));

      return result.rowCount ?? 0;
    } catch (error) {
      console.error('Error deleting expired email verification tokens:', error);
      return 0;
    }
  }

  private async getBrandingAppName(): Promise<string> {
    const brandingSetting = await this.getAppSetting('branding');
    const brandingValue = brandingSetting?.value as { appName?: string } | undefined;
    return typeof brandingValue?.appName === 'string' && brandingValue.appName.trim()
      ? brandingValue.appName.trim()
      : 'BotHive';
  }

