  async updatePartnerConfiguration(id: number, data: Partial<Omit<PartnerConfiguration, 'id' | 'createdAt'>>): Promise<PartnerConfiguration> {
    try {
      let payload = { ...data };
      if (
        data.partnerSecret !== undefined ||
        data.accessToken !== undefined ||
        data.webhookVerifyToken !== undefined
      ) {
        const [existing] = await db
          .select()
          .from(partnerConfigurations)
          .where(eq(partnerConfigurations.id, id))
          .limit(1);
        if (existing?.provider === 'tiktok') {
          payload = encryptTikTokPartnerConfigurationForWrite({
            ...payload,
            provider: 'tiktok',
          }) as Partial<Omit<PartnerConfiguration, 'id' | 'createdAt'>>;
        }
      }

      const [config] = await db
        .update(partnerConfigurations)
        .set({ ...payload, updatedAt: new Date() })
        .where(eq(partnerConfigurations.id, id))
        .returning();
      return config;
    } catch (error) {
      console.error("Error updating partner configuration:", error);
      throw error;
    }
  }

