  async deleteContactDocumentAndClearReferences(contactId: number, documentId: number): Promise<string[]> {
    return db.transaction(async (tx: any) => {
      const [contact] = await tx.select({ customFields: contacts.customFields }).from(contacts).where(eq(contacts.id, contactId)).limit(1);
      const current = contact?.customFields && typeof contact.customFields === 'object' && !Array.isArray(contact.customFields)
        ? contact.customFields as Record<string, unknown>
        : {};
      const next = { ...current };
      const clearedFields: string[] = [];
      for (const [fieldName, value] of Object.entries(current)) {
        if (value && typeof value === 'object' && !Array.isArray(value) &&
            (value as { source?: unknown }).source === 'contact_document' &&
            Number((value as { id?: unknown }).id) === documentId) {
          delete next[fieldName];
          clearedFields.push(fieldName);
        }
      }
      if (clearedFields.length > 0) {
        await tx.update(contacts).set({ customFields: next, updatedAt: new Date() }).where(eq(contacts.id, contactId));
      }
      await tx.delete(contactDocuments).where(and(eq(contactDocuments.id, documentId), eq(contactDocuments.contactId, contactId)));
      return clearedFields;
    });
  }

