  async deleteCustomFieldAttachmentAndClearReferences(
    companyId: number,
    id: number,
  ): Promise<{ attachment?: CustomFieldAttachment; clearedFields: string[] }> {
    return db.transaction(async (tx: any) => {
      const [attachment] = await tx
        .select()
        .from(customFieldAttachments)
        .where(and(eq(customFieldAttachments.companyId, companyId), eq(customFieldAttachments.id, id)))
        .limit(1);
      if (!attachment) return { clearedFields: [] };

      const ownerId = attachment.ownerType === 'contact' ? attachment.contactId : attachment.dealId;
      const table = attachment.ownerType === 'contact' ? contacts : deals;
      if (!ownerId) return { attachment, clearedFields: [] };
      const [owner] = await tx.select({ customFields: table.customFields }).from(table).where(eq(table.id, ownerId)).limit(1);
      const current = owner?.customFields && typeof owner.customFields === 'object' && !Array.isArray(owner.customFields)
        ? owner.customFields as Record<string, unknown>
        : {};
      const next = { ...current };
      const clearedFields: string[] = [];
      for (const [fieldName, value] of Object.entries(current)) {
        if (value && typeof value === 'object' && !Array.isArray(value) &&
            (value as { source?: unknown }).source === 'custom_field_attachment' &&
            Number((value as { id?: unknown }).id) === id) {
          delete next[fieldName];
          clearedFields.push(fieldName);
        }
      }
      if (clearedFields.length > 0) {
        await tx.update(table).set({ customFields: next, updatedAt: new Date() }).where(eq(table.id, ownerId));
      }
      const [deleted] = await tx
        .delete(customFieldAttachments)
        .where(and(eq(customFieldAttachments.companyId, companyId), eq(customFieldAttachments.id, id)))
        .returning();
      return { attachment: deleted, clearedFields };
    });
  }

  async clearCustomFieldFileReferences(
    ownerType: 'contact' | 'deal',
    ownerId: number,
    source: 'custom_field_attachment' | 'contact_document',
    fileId: number,
  ): Promise<string[]> {
    const entity = ownerType === 'contact' ? await this.getContact(ownerId) : await this.getDeal(ownerId);
    if (!entity) return [];
    const current = entity.customFields && typeof entity.customFields === 'object' && !Array.isArray(entity.customFields)
      ? entity.customFields as Record<string, unknown>
      : {};
    const next = { ...current };
    const cleared: string[] = [];
    for (const [fieldName, value] of Object.entries(current)) {
      if (
        value && typeof value === 'object' && !Array.isArray(value) &&
        (value as { source?: unknown }).source === source &&
        Number((value as { id?: unknown }).id) === fileId
      ) {
        delete next[fieldName];
        cleared.push(fieldName);
      }
    }
    if (cleared.length > 0) {
      if (ownerType === 'contact') await this.updateContact(ownerId, { customFields: next });
      else await this.updateDeal(ownerId, { customFields: next });
    }
    return cleared;
  }


