  async reorderCompanyCustomFields(companyId: number, entity: 'deal' | 'contact' | 'company', customFieldIds: number[]): Promise<boolean> {
    try {
      if (customFieldIds.length === 0) return true;

      const companyFields = await this.getCompanyCustomFields(companyId, entity);
      const companyFieldIds = new Set(companyFields.map((f: any) => f.id));

      const invalidIds = customFieldIds.filter(id => !companyFieldIds.has(id));
      if (invalidIds.length > 0) {
        throw new Error(`Invalid custom field IDs: ${invalidIds.join(', ')}. These fields do not belong to your company or entity.`);
      }

      const uniqueIds = new Set(customFieldIds);
      if (uniqueIds.size !== customFieldIds.length) {
        throw new Error('Duplicate custom field IDs found in reorder request');
      }

      return await db.transaction(async (tx: any) => {
        for (let i = 0; i < customFieldIds.length; i++) {
          await tx
            .update(companyCustomFields)
            .set({
              displayOrder: i,
              updatedAt: new Date(),
            })
            .where(
              and(
                eq(companyCustomFields.id, customFieldIds[i]),
                eq(companyCustomFields.companyId, companyId),
                eq(companyCustomFields.entity, entity)
              )
            );
        }
        return true;
      });
    } catch (error) {
      console.error('Error reordering custom fields:', error);
      throw error;
    }
  }

