  async createProductCategory(category: InsertProductCategory): Promise<ProductCategory> {
    if (category.parentCategoryId != null) {
      await assertProductCategoryInCompany(category.parentCategoryId, category.companyId);
    }
    const [row] = await db.insert(productCategories).values(category).returning();
    if (!row) throw new Error("Failed to create product category");
    return row;
  }

  async updateProductCategory(id: number, updates: Partial<InsertProductCategory>): Promise<ProductCategory> {
    const [existing] = await db.select().from(productCategories).where(eq(productCategories.id, id));
    if (!existing) throw new Error("Product category not found");
    const next: Partial<InsertProductCategory> = { ...updates };
    delete (next as { companyId?: number }).companyId;
    if (next.parentCategoryId !== undefined && next.parentCategoryId !== null) {
      if (next.parentCategoryId === id) {
        throw new ErpProductScopeError("Category cannot be its own parent");
      }
      await assertProductCategoryInCompany(next.parentCategoryId, existing.companyId);
    }
    const [row] = await db
      .update(productCategories)
      .set({ ...next, updatedAt: new Date() })
      .where(eq(productCategories.id, id))
      .returning();
    if (!row) throw new Error("Product category not found");
    return row;
  }

