  async createProductVariant(variant: InsertProductVariant): Promise<ProductVariant> {
    const product = await this.getProduct(variant.productId);
    if (!product || product.companyId !== variant.companyId) {
      throw new ErpProductScopeError("Product does not belong to this company");
    }
    const nextSku = typeof variant.sku === "string" ? variant.sku.trim() : "";
    if (nextSku) {
      const existingVariant = await this.getVariantBySku(variant.companyId, nextSku);
      if (existingVariant) {
        throw new ErpValidationError("Variant SKU already exists in this company");
      }
    }
    const [row] = await db.insert(productVariants).values(variant).returning();
    if (!row) throw new Error("Failed to create product variant");
    return row;
  }

  async updateProductVariant(id: number, updates: Partial<InsertProductVariant>): Promise<ProductVariant> {
    const [existing] = await db.select().from(productVariants).where(eq(productVariants.id, id));
    if (!existing) throw new Error("Product variant not found");
    const next: Partial<InsertProductVariant> = { ...updates };
    delete (next as { companyId?: number }).companyId;
    delete (next as { productId?: number }).productId;
    if (typeof next.sku === "string") {
      const normalizedSku = next.sku.trim();
      next.sku = normalizedSku.length > 0 ? normalizedSku : null;
    }
    const skuToValidate = (next.sku ?? existing.sku)?.trim();
    if (skuToValidate) {
      const existingVariant = await this.getVariantBySku(existing.companyId, skuToValidate, id);
      if (existingVariant) {
        throw new ErpValidationError("Variant SKU already exists in this company");
      }
    }
    const [row] = await db
      .update(productVariants)
      .set({ ...next, updatedAt: new Date() })
      .where(eq(productVariants.id, id))
      .returning();
    if (!row) throw new Error("Product variant not found");
    return row;
  }

  async deleteProductVariant(id: number): Promise<boolean> {
    const result = await db.delete(productVariants).where(eq(productVariants.id, id));
    return (result.rowCount ?? 0) > 0;
  }

