  async createRestaurantTablesBulk(companyId: number, tables: InsertRestaurantTable[]): Promise<RestaurantTable[]> {
    if (tables.length === 0) return [];
    const normalized = tables.map((table) => ({
      ...table,
      companyId,
      code: table.code.trim(),
      label: table.label.trim(),
    }));

    const duplicateCodes = new Set<string>();
    const duplicateLabels = new Set<string>();
    const seenCode = new Set<string>();
    const seenLabel = new Set<string>();
    for (const table of normalized) {
      const codeKey = table.code.toLowerCase();
      const labelKey = table.label.toLowerCase();
      if (seenCode.has(codeKey)) duplicateCodes.add(table.code);
      seenCode.add(codeKey);
      if (seenLabel.has(labelKey)) duplicateLabels.add(table.label);
      seenLabel.add(labelKey);
    }
    if (duplicateCodes.size > 0) {
      throw new ErpValidationError(
        `Duplicate table codes in request: ${Array.from(duplicateCodes).sort().join(", ")}`
      );
    }
    if (duplicateLabels.size > 0) {
      throw new ErpValidationError(
        `Duplicate table labels in request: ${Array.from(duplicateLabels).sort().join(", ")}`
      );
    }

    return db.transaction(async (tx: any) => {
      const requestedSectionIds = Array.from(
        new Set(
          normalized
            .map((table) => table.sectionId)
            .filter((sectionId): sectionId is number => sectionId != null)
        )
      );
      if (requestedSectionIds.length > 0) {
        const sections = await tx
          .select({ id: restaurantSections.id })
          .from(restaurantSections)
          .where(
            and(
              eq(restaurantSections.companyId, companyId),
              inArray(restaurantSections.id, requestedSectionIds)
            )
          );
        if (sections.length !== requestedSectionIds.length) {
          throw new ErpValidationError("One or more floors do not belong to this company");
        }
      }

      const requestedCodes = normalized.map((table) => table.code);
      const requestedLabels = normalized.map((table) => table.label);
      const existingConflicts = await tx
        .select({ code: restaurantTables.code, label: restaurantTables.label })
        .from(restaurantTables)
        .where(
          and(
            eq(restaurantTables.companyId, companyId),
            or(
              inArray(restaurantTables.code, requestedCodes),
              inArray(restaurantTables.label, requestedLabels)
            )
          )
        );
      if (existingConflicts.length > 0) {
        const conflictCodes = existingConflicts
          .map((row: { code: RestaurantTable["code"]; label: RestaurantTable["label"] }) => row.code)
          .filter(Boolean)
          .join(", ");
        const conflictLabels = existingConflicts
          .map((row: { code: RestaurantTable["code"]; label: RestaurantTable["label"] }) => row.label)
          .filter(Boolean)
          .join(", ");
        throw new ErpConflictError(
          `Table code/label already exists${conflictCodes || conflictLabels ? ` (${[conflictCodes, conflictLabels].filter(Boolean).join(" | ")})` : ""}`
        );
      }

      const sectionIds = Array.from(new Set(normalized.map((table) => table.sectionId ?? null)));
      const nonNullSectionIds = sectionIds.filter((value): value is number => value != null);
      const existingRows = await tx
        .select({ sectionId: restaurantTables.sectionId })
        .from(restaurantTables)
        .where(
          and(
            eq(restaurantTables.companyId, companyId),
            sectionIds.includes(null)
              ? (nonNullSectionIds.length > 0
                  ? or(isNull(restaurantTables.sectionId), inArray(restaurantTables.sectionId, nonNullSectionIds))
                  : isNull(restaurantTables.sectionId))
              : inArray(restaurantTables.sectionId, nonNullSectionIds)
          )
        );
      const existingCountBySection = new Map<string, number>();
      for (const row of existingRows) {
        const key = String(row.sectionId ?? 'none');
        existingCountBySection.set(key, (existingCountBySection.get(key) ?? 0) + 1);
      }
      const createdCountBySection = new Map<string, number>();
      const withPositionedLayout = normalized.map((table) => {
        const key = String(table.sectionId ?? 'none');
        const startOffset = existingCountBySection.get(key) ?? 0;
        const createdOffset = createdCountBySection.get(key) ?? 0;
        const layoutIndex = startOffset + createdOffset;
        createdCountBySection.set(key, createdOffset + 1);
        const col = layoutIndex % 8;
        const row = Math.floor(layoutIndex / 8);
        return {
          ...table,
          posX: 24 + col * 128,
          posY: 24 + row * 88,
          layoutWidth: table.layoutWidth ?? 100,
          layoutHeight: table.layoutHeight ?? 64,
          rotation: table.rotation ?? 0,
          tableShape: table.tableShape ?? "rectangle",
          tableType: table.tableType ?? "dining",
        };
      });

      const inserted = await tx.insert(restaurantTables).values(withPositionedLayout).returning();
      if (inserted.length !== normalized.length) {
        throw new Error("Failed to create all restaurant tables");
      }
      return inserted;
    });
  }

  async updateRestaurantTable(id: number, updates: Partial<InsertRestaurantTable>): Promise<RestaurantTable> {
    const [existing] = await db.select().from(restaurantTables).where(eq(restaurantTables.id, id));
    if (!existing) throw new ErpValidationError("Restaurant table not found");
    const next: Partial<InsertRestaurantTable> = { ...updates };
    delete (next as { companyId?: number }).companyId;
    if (next.sectionId != null) {
      const [section] = await db.select().from(restaurantSections).where(and(eq(restaurantSections.id, next.sectionId), eq(restaurantSections.companyId, existing.companyId)));
      if (!section) throw new ErpValidationError("Restaurant section does not belong to this company");
    }
    const [row] = await db.update(restaurantTables).set({ ...next, updatedAt: new Date() }).where(eq(restaurantTables.id, id)).returning();
    if (!row) throw new Error("Restaurant table not found");
    return row;
  }

  async deleteRestaurantTable(companyId: number, id: number): Promise<boolean> {
    const [ctx] = await db.select({ id: restaurantOrderContexts.id }).from(restaurantOrderContexts).where(and(eq(restaurantOrderContexts.companyId, companyId), eq(restaurantOrderContexts.tableId, id))).limit(1);
    if (ctx) throw new ErpConflictError("Cannot delete table with operational history");
    const [reservation] = await db.select({ id: restaurantReservations.id }).from(restaurantReservations).where(and(eq(restaurantReservations.companyId, companyId), eq(restaurantReservations.tableId, id))).limit(1);
    if (reservation) throw new ErpConflictError("Cannot delete table with reservation history; deactivate it instead");
    const [waitlist] = await db.select({ id: restaurantWaitlistEntries.id }).from(restaurantWaitlistEntries).where(and(eq(restaurantWaitlistEntries.companyId, companyId), eq(restaurantWaitlistEntries.targetTableId, id))).limit(1);
    if (waitlist) throw new ErpConflictError("Cannot delete table with waitlist history; deactivate it instead");
    const [token] = await db.select({ id: restaurantTableQrTokens.id }).from(restaurantTableQrTokens).where(and(eq(restaurantTableQrTokens.companyId, companyId), eq(restaurantTableQrTokens.tableId, id), eq(restaurantTableQrTokens.isActive, true))).limit(1);
    if (token) throw new ErpConflictError("Cannot delete table with active QR token");
    const result = await db.delete(restaurantTables).where(and(eq(restaurantTables.companyId, companyId), eq(restaurantTables.id, id)));
    return (result.rowCount ?? 0) > 0;
  }

