  async createRestaurantReservation(data: InsertRestaurantReservation): Promise<RestaurantReservation> {
    if (!data.guestName?.trim() || !data.guestPhone?.trim()) throw new ErpValidationError("Guest name and phone are required");
    if (data.contactId != null) {
      const [contact] = await db.select().from(contacts).where(and(eq(contacts.id, data.contactId), eq(contacts.companyId, data.companyId)));
      if (!contact) throw new ErpValidationError("Contact does not belong to this company");
    }
    if (data.tableId != null) {
      const [table] = await db.select().from(restaurantTables).where(and(eq(restaurantTables.id, data.tableId), eq(restaurantTables.companyId, data.companyId)));
      if (!table) throw new ErpValidationError("Restaurant table does not belong to this company");
    }
    const [row] = await db.insert(restaurantReservations).values(data).returning();
    if (!row) throw new Error("Failed to create reservation");
    return row;
  }

