    const [existing] = await db.select().from(restaurantReservations).where(eq(restaurantReservations.id, id));
    if (!existing) throw new ErpValidationError("Restaurant reservation not found");
    const next: Partial<InsertRestaurantReservation> = { ...updates };
    delete (next as { companyId?: number }).companyId;
    if (next.contactId != null) {
      const [contact] = await db.select().from(contacts).where(and(eq(contacts.id, next.contactId), eq(contacts.companyId, existing.companyId)));
      if (!contact) throw new ErpValidationError("Contact does not belong to this company");
    }
    if (next.tableId != null) {
      const [table] = await db.select().from(restaurantTables).where(and(eq(restaurantTables.id, next.tableId), eq(restaurantTables.companyId, existing.companyId)));
      if (!table) throw new ErpValidationError("Restaurant table does not belong to this company");
    }
    const [row] = await db.update(restaurantReservations).set({ ...next, updatedAt: new Date() }).where(eq(restaurantReservations.id, id)).returning();
    if (!row) throw new Error("Restaurant reservation not found");
    return row;
