  async createDentalChartSnapshot(data: Omit<InsertDentalChartSnapshot, 'version'>): Promise<DentalChartSnapshot> {
    const patient = await this.getDentalPatientByContactId(data.companyId, data.contactId);
    if (!patient) throw new ErpValidationError('Dental patient profile not found');

    const insertSnapshot = () =>
      db.transaction(async (tx: any) => {
        const [maxRow] = await tx
          .select({ maxVersion: sql<number>`COALESCE(MAX(${dentalChartSnapshots.version}), 0)` })
          .from(dentalChartSnapshots)
          .where(
            and(
              eq(dentalChartSnapshots.companyId, data.companyId),
              eq(dentalChartSnapshots.contactId, data.contactId),
            ),
          );
        const version = Number(maxRow?.maxVersion ?? 0) + 1;
        const [row] = await tx
          .insert(dentalChartSnapshots)
          .values({ ...data, version })
          .returning();
        if (!row) throw new Error('Failed to create dental chart snapshot');
        return row;
      });

    const maxAttempts = 3;
    for (let attempt = 0; attempt < maxAttempts; attempt++) {
      try {
        return await insertSnapshot();
      } catch (error: unknown) {
        const pgError = error as { code?: string };
        if (pgError?.code !== '23505' || attempt === maxAttempts - 1) throw error;
      }
    }

    throw new Error('Failed to create dental chart snapshot');
  }

