  async createDentalClinicalNote(data: InsertDentalClinicalNote): Promise<DentalClinicalNote> {
    const patient = await this.getDentalPatientByContactId(data.companyId, data.contactId);
    if (!patient) throw new ErpValidationError('Dental patient profile not found');
    return db.transaction(async (tx: any) => {
      const [row] = await tx.insert(dentalClinicalNotes).values({ ...data, revisionNumber: 1 }).returning();
      if (!row) throw new Error('Failed to create dental clinical note');
      await tx.insert(dentalClinicalNoteRevisions).values({
        companyId: row.companyId,
        noteId: row.id,
        revisionNumber: 1,
        action: 'create',
        noteType: row.noteType,
        body: row.body,
        toothRefs: row.toothRefs,
        treatmentPlanId: row.treatmentPlanId,
        treatmentPlanTitleSnapshot: row.treatmentPlanTitleSnapshot,
        isPrivate: row.isPrivate,
        actedBy: row.createdBy,
        actedAt: row.createdAt ?? new Date(),
      });
      return row;
    });
  }

  async amendDentalClinicalNote(
    companyId: number,
    noteId: number,
    updates: Partial<Omit<InsertDentalClinicalNote, 'companyId' | 'contactId' | 'createdBy' | 'createdAt' | 'isPrivate'>>,
    actorId: number,
    reason?: string | null,
  ): Promise<DentalClinicalNote> {
    const existing = await this.getDentalClinicalNote(companyId, noteId);
    if (!existing) throw new ErpValidationError('Dental clinical note not found');
    if (existing.voidedAt) throw new ErpValidationError('Voided clinical notes cannot be amended');
    return db.transaction(async (tx: any) => {
      const revisionNumber = existing.revisionNumber + 1;
      const [row] = await tx
        .update(dentalClinicalNotes)
        .set({ ...updates, revisionNumber, updatedBy: actorId, updatedAt: new Date() })
        .where(and(
          eq(dentalClinicalNotes.companyId, companyId),
          eq(dentalClinicalNotes.id, noteId),
          eq(dentalClinicalNotes.revisionNumber, existing.revisionNumber),
          isNull(dentalClinicalNotes.voidedAt),
        ))
        .returning();
      if (!row) throw new ErpConflictError('Clinical note was changed by another user');
      await tx.insert(dentalClinicalNoteRevisions).values({
        companyId,
        noteId,
        revisionNumber,
        action: 'amend',
        noteType: row.noteType,
        body: row.body,
        toothRefs: row.toothRefs,
        treatmentPlanId: row.treatmentPlanId,
        treatmentPlanTitleSnapshot: row.treatmentPlanTitleSnapshot,
        isPrivate: row.isPrivate,
        reason: reason?.trim() || null,
        actedBy: actorId,
      });
      return row;
    });
  }

  async voidDentalClinicalNote(companyId: number, noteId: number, actorId: number, reason: string): Promise<DentalClinicalNote> {
    const existing = await this.getDentalClinicalNote(companyId, noteId);
    if (!existing) throw new ErpValidationError('Dental clinical note not found');
    if (existing.voidedAt) throw new ErpValidationError('Clinical note is already voided');
    return db.transaction(async (tx: any) => {
      const now = new Date();
      const revisionNumber = existing.revisionNumber + 1;
      const [row] = await tx.update(dentalClinicalNotes).set({
        voidedAt: now,
        voidedBy: actorId,
        voidReason: reason.trim(),
        revisionNumber,
        updatedBy: actorId,
        updatedAt: now,
      }).where(and(
        eq(dentalClinicalNotes.companyId, companyId),
        eq(dentalClinicalNotes.id, noteId),
        eq(dentalClinicalNotes.revisionNumber, existing.revisionNumber),
        isNull(dentalClinicalNotes.voidedAt),
      )).returning();
      if (!row) throw new ErpConflictError('Clinical note was changed by another user');
      await tx.insert(dentalClinicalNoteRevisions).values({
        companyId,
        noteId,
        revisionNumber,
        action: 'void',
        noteType: row.noteType,
        body: row.body,
        toothRefs: row.toothRefs,
        treatmentPlanId: row.treatmentPlanId,
        treatmentPlanTitleSnapshot: row.treatmentPlanTitleSnapshot,
        isPrivate: row.isPrivate,
        reason: reason.trim(),
        actedBy: actorId,
        actedAt: now,
      });
      return row;
    });
  }

