  async getSupplierUsage(companyId: number, supplierId: number): Promise<SupplierUsageSummary> {
    const [linkedProductsResult, openPurchaseOrdersResult, unpaidInvoicesResult, openAccountsPayableResult] =
      await Promise.all([
        db
          .select({ count: sql<number>`COUNT(*)::int` })
          .from(supplierProducts)
          .where(and(eq(supplierProducts.companyId, companyId), eq(supplierProducts.supplierId, supplierId))),
        db
          .select({ count: sql<number>`COUNT(*)::int` })
          .from(purchaseOrders)
          .where(
            and(
              eq(purchaseOrders.companyId, companyId),
              eq(purchaseOrders.supplierId, supplierId),
              ne(purchaseOrders.status, "cancelled")
            )
          ),
        db
          .select({ count: sql<number>`COUNT(*)::int` })
          .from(invoices)
          .where(
            and(
              eq(invoices.companyId, companyId),
              eq(invoices.supplierId, supplierId),
              not(inArray(invoices.status, ["paid", "cancelled", "void"]))
            )
          ),
        db
          .select({ count: sql<number>`COUNT(*)::int` })
          .from(accountsPayable)
          .where(
            and(
              eq(accountsPayable.companyId, companyId),
              eq(accountsPayable.supplierId, supplierId),
              not(inArray(accountsPayable.status, ["paid", "written_off"]))
            )
          ),
      ]);

    return {
      linkedProducts: Number(linkedProductsResult[0]?.count ?? 0),
      openPurchaseOrders: Number(openPurchaseOrdersResult[0]?.count ?? 0),
      unpaidInvoices: Number(unpaidInvoicesResult[0]?.count ?? 0),
      openAccountsPayable: Number(openAccountsPayableResult[0]?.count ?? 0),
    };
  }

  async getSupplierProductsByProduct(productId: number): Promise<SupplierProduct[]> {
    return db
      .select()
      .from(supplierProducts)
      .where(eq(supplierProducts.productId, productId))
      .orderBy(desc(supplierProducts.createdAt));
  }

