          if(!targetJournal||targetJournal.status!=='posted'||targetJournal.transactionCurrency!==invoice.currency||targetJournal.baseCurrency!==base)throw new ErpConflictError('Credit allocation target journal requires reconciliation');
          if(debits.length!==1||credits.length!==1||units(debits[0].debit)!==amount||units(credits[0].credit)!==amount||subtractErpDecimals(debits[0].debitBase!,debits[0].creditBase!,6)!==roundErpDecimal(String(disposition.source_base_amount),6)||subtractErpDecimals(credits[0].creditBase!,credits[0].debitBase!,6)!==roundErpDecimal(String(disposition.target_base_amount),6))throw new ErpConflictError('Credit allocation retained amounts require reconciliation');
