        const original=await this.getJournalEntry(s.journal_entry_id),payable=await this.getChartOfAccount(s.lines.payableAccountId);if(!original||original.status!=='posted'||original.companyId!==companyId||original.transactionCurrency!==s.currency||original.baseCurrency!==c.basis.baseCurrency||!payable?.isActive||payable.companyId!==companyId||payable.type!=='liability'||payable.id===c.accountId)throw new ErpValidationError('Reconcile fee payable accounts/currencies');
