      const units=(v:unknown)=>erpMinorUnits(String(v),6),signedUnits=(v:unknown)=>String(v).startsWith('-')?-units(String(v).slice(1)):units(v),money=(v:bigint)=>v<0n?'-'+erpMinorUnitsToAmount(-v,6):erpMinorUnitsToAmount(v,6);
      const digits=erpCurrencyDigits(s.lines.transactionDecimalPlaces??await this.invoiceCurrencyDigitsWithTx(tx,companyId,s.currency)),cashDigits=await this.invoiceCurrencyDigitsWithTx(tx,companyId,base.baseCurrency);let baseDigits=cashDigits;
      const expenseAllocations=await this.initialSettlementExpensesWithTx(tx,companyId,s.currency,base.baseCurrency,s.lines.items,settlementId);
      for(const item of s.lines.items){
        const rent=item.type==='rent_receipt',expense=expenseAllocations.get(item),components=rent?[item]:expense.recoveryComponents;
        const retained:any[]=[];
        for(const part of components){const accountId=rent?part.ownerFundsAccountId:(part.recoveryAccountId??part.expenseAccountId),a=await this.getChartOfAccount(accountId);
          if(!a||a.companyId!==companyId||!a.isActive||(rent?a.type!=='liability':!['expense','asset','liability'].includes(a.type)))throw new ErpValidationError('Settlement source account is invalid');
          const sign=rent?1n:-1n,carrying=rent?await this.settlementItemCarryingBaseWithTx(tx,companyId,s.currency,base.baseCurrency,part,allocated):{baseAmount:part.baseAmount,sourceJournalId:part.sourceJournalId,baseDecimalPlaces:expense.baseDecimalPlaces},old=group.get(accountId)??{amount:0n,base:0n};
          baseDigits=Math.max(baseDigits,erpCurrencyDigits(carrying.baseDecimalPlaces));group.set(accountId,{amount:old.amount+signedUnits(part.amount)*sign,base:old.base+signedUnits(carrying.baseAmount)*sign});retained.push({...part,...carrying});
        }
        carryingItems.push(rent?retained[0]:{...expense,recoveryComponents:retained,sourceJournalId:retained[0]?.sourceJournalId??expense.sourceJournalId,baseAmount:money(retained.reduce((sum,part)=>sum+signedUnits(part.baseAmount),0n))});
      }
      const adjustmentItems:any[]=[];
      let adjustmentCents=0n;
      for(const item of s.lines.adjustmentItems??[]){
        const amount=signedUnits(item.amount),a=await this.getChartOfAccount(item.accountId);
        if(!amount||!item.reason||!a||a.companyId!==companyId||!a.isActive||a.type!==(amount>0n?'expense':'revenue'))throw new ErpValidationError('Settlement adjustment account requires reconciliation');
        const converted=await this.toBaseCurrencyAmount(companyId,money(amount<0n?-amount:amount),s.currency,date),old=group.get(a.id)??{amount:0n,base:0n};
        group.set(a.id,{amount:old.amount+amount,base:old.base+units(roundErpDecimal(String(converted.baseAmount),cashDigits))*(amount>0n?1n:-1n)});
        erpMinorUnits(item.amount.startsWith('-')?item.amount.slice(1):item.amount,digits);adjustmentCents+=amount;adjustmentItems.push({...item,baseAmount:roundErpDecimal(String(converted.baseAmount),cashDigits),exchangeRate:String(converted.exchangeRate),baseCurrency:converted.baseCurrency});
      }
