      lines.push({journalEntryId:0,accountId:s.lines.payableAccountId,debit:'0',credit:String(s.payable),debitBase:'0',creditBase:postingBasis.payableBaseAmount,description:'Owner settlement payable'});
      await requireRealEstateSettlementActor(companyId,userId,settlementId,s.owner_contact_id);
      const journal=await this.createJournalEntryWithTx(tx,{companyId,entryNumber:'',date,description:`Owner settlement #${settlementId} / ${s.period_key}`,referenceType:'adjustment',referenceId:null,status:'draft',createdBy:userId,transactionCurrency:s.currency,baseCurrency:base.baseCurrency,exchangeRate:String(base.exchangeRate),transactionDecimalPlaces:digits,baseDecimalPlaces:baseDigits} as any,lines,companyId);await this.postJournalEntryWithTx(tx,journal.id,userId,companyId);
