    const units=(v:unknown)=>erpMinorUnits(String(v),6),signedUnits=(v:unknown)=>String(v).startsWith('-')?-units(String(v).slice(1)):units(v),money=(v:bigint,digits=6)=>{const text=erpMinorUnitsToAmount(erpMinorUnits(erpMinorUnitsToAmount(v<0n?-v:v,6),digits),digits);return v<0n?'-'+text:text;};
