    if(portions.some((i:any)=>!Array.isArray(i.recoveryComponents)||i.originalAmount==null&&Number(i.amount)<=0||Number(i.expenseAccountId)!==Number(basis.net_account_id)))throw new ErpValidationError('Reconcile legacy owner expense snapshots before correction');
