        for(const id of new Set<number>(ids)){const j=await this.getJournalEntry(id);if(!j||j.companyId!==companyId||!['posted','reversed'].includes(j.status)||j.transactionCurrency!==s.currency||j.baseCurrency!==original.baseCurrency)throw new ErpValidationError('Reconcile owner payout and correction history');}
