  async upsertAccountReceivable(ar: InsertAccountReceivable | AccountReceivable): Promise<AccountReceivable> {
    const existingId = 'id' in ar ? ar.id : undefined;
    const existing = existingId ? await this.getAccountReceivable(existingId) : null;
    if (!existing && 'invoiceId' in ar) {
      const byInvoice = await this.getAccountReceivableByInvoice(ar.companyId, ar.invoiceId);
      if (byInvoice) {
        const result = await db.update(accountsReceivable).set({
          contactId: ar.contactId ?? byInvoice.contactId,
          journalEntryId: ar.journalEntryId ?? byInvoice.journalEntryId,
          amount: ar.amount ?? byInvoice.amount,
          paidAmount: ar.paidAmount ?? byInvoice.paidAmount,
          dueDate: ar.dueDate ?? byInvoice.dueDate,
          status: (ar as AccountReceivable).status ?? byInvoice.status,
          updatedAt: new Date(),
        }).where(eq(accountsReceivable.id, byInvoice.id)).returning();
        return result[0];
      }
    }
    if (existing) {
      const result = await db.update(accountsReceivable).set({
        contactId: ar.contactId ?? existing.contactId,
        journalEntryId: ar.journalEntryId ?? existing.journalEntryId,
        amount: ar.amount ?? existing.amount,
        paidAmount: ar.paidAmount ?? existing.paidAmount,
        dueDate: ar.dueDate ?? existing.dueDate,
        status: (ar as AccountReceivable).status ?? existing.status,
        updatedAt: new Date(),
      }).where(eq(accountsReceivable.id, existing.id)).returning();
      return result[0];
    }
    const result = await db.insert(accountsReceivable).values({
      ...(ar as InsertAccountReceivable),
      createdAt: new Date(),
      updatedAt: new Date(),
    }).returning();
    return result[0];
  }

