  async getDepartment(id: number): Promise<Department | undefined> {
    const [row] = await db.select().from(departments).where(eq(departments.id, id));
    return row;
  }

  private async assertDepartmentHierarchyScoped(dept: InsertDepartment, excludeDepartmentId?: number): Promise<void> {
    if (dept.managerId != null) {
      const u = await this.getUser(dept.managerId);
      if (!u || u.companyId !== dept.companyId) {
        throw new Error("Department manager must be a user in the same company");
      }
    }
    if (dept.parentDepartmentId != null) {
      if (excludeDepartmentId != null && dept.parentDepartmentId === excludeDepartmentId) {
        throw new Error("Department cannot be its own parent");
      }
      const parent = await this.getDepartment(dept.parentDepartmentId);
      if (!parent || parent.companyId !== dept.companyId) {
        throw new Error("Parent department must belong to the same company");
      }
      const visited = new Set<number>();
      let current: Department | undefined = parent;
      while (current) {
        if (excludeDepartmentId != null && current.id === excludeDepartmentId) {
          throw new Error("Department parent cannot create a reporting cycle");
        }
        if (visited.has(current.id)) {
          throw new Error("Department hierarchy contains a reporting cycle");
        }
        visited.add(current.id);
        if (current.parentDepartmentId == null) break;
        current = await this.getDepartment(current.parentDepartmentId);
        if (current && current.companyId !== dept.companyId) {
          throw new Error("Parent department must belong to the same company");
        }
      }
    }
  }

  private async assertEmployeeManagerScoped(
    companyId: number,
    managerEmployeeId: number,
    forEmployeeId?: number
  ): Promise<void> {
    if (forEmployeeId != null && managerEmployeeId === forEmployeeId) {
      throw new Error("Employee cannot be their own manager");
    }
    const mgr = await this.getEmployee(managerEmployeeId);
    if (!mgr || mgr.companyId !== companyId) {
      throw new Error("Manager must be an employee in the same company");
    }
    const visited = new Set<number>();
    let current: Employee | undefined = mgr;
    while (current) {
      if (forEmployeeId != null && current.id === forEmployeeId) {
        throw new Error("Employee manager cannot create a reporting cycle");
      }
      if (visited.has(current.id)) {
        throw new Error("Employee hierarchy contains a reporting cycle");
      }
      visited.add(current.id);
      if (current.managerId == null) break;
      current = await this.getEmployee(current.managerId);
      if (current && current.companyId !== companyId) {
        throw new Error("Manager must be an employee in the same company");
      }
    }
  }

  async createDepartment(dept: InsertDepartment): Promise<Department> {
    await this.assertDepartmentHierarchyScoped(dept);
    const [row] = await db.insert(departments).values(dept).returning();
    if (!row) throw new Error("Failed to create department");
    return row;
  }

  async updateDepartment(id: number, updates: Partial<InsertDepartment>): Promise<Department> {
    const [existing] = await db.select().from(departments).where(eq(departments.id, id));
    if (!existing) throw new Error("Department not found");
    const merged: InsertDepartment = {
      companyId: existing.companyId,
      name: updates.name ?? existing.name,
      managerId: updates.managerId !== undefined ? updates.managerId : existing.managerId,
      parentDepartmentId:
        updates.parentDepartmentId !== undefined ? updates.parentDepartmentId : existing.parentDepartmentId,
      description: updates.description !== undefined ? updates.description : existing.description,
    };
    await this.assertDepartmentHierarchyScoped(merged, id);
    const next = { ...updates };
    delete (next as { companyId?: number }).companyId;
    const [row] = await db
      .update(departments)
      .set({ ...next, updatedAt: new Date() })
      .where(eq(departments.id, id))
      .returning();
    if (!row) throw new Error("Department not found");
    return row;
  }

  async deleteDepartment(id: number): Promise<boolean> {
    const result = await db.delete(departments).where(eq(departments.id, id));
    return (result.rowCount ?? 0) > 0;
  }

  async generateEmployeeId(companyId: number): Promise<string> {
    const rows = await db
      .select({ employeeId: employees.employeeId })
      .from(employees)
      .where(eq(employees.companyId, companyId));
    let max = 0;
    for (const r of rows) {
      const m = /^EMP-(\d+)$/i.exec((r.employeeId ?? "").trim());
      if (m) max = Math.max(max, parseInt(m[1], 10));
    }
    return `EMP-${String(max + 1).padStart(4, "0")}`;
  }

  async getEmployees(
    companyId: number,
    filters?: { departmentId?: number; status?: string; search?: string; limit?: number; offset?: number }
  ): Promise<{ data: Employee[]; total: number }> {
    const conditions: SQL[] = [eq(employees.companyId, companyId)];
    if (filters?.departmentId != null) {
      conditions.push(eq(employees.departmentId, filters.departmentId));
    }
    if (filters?.status) {
      conditions.push(eq(employees.status, filters.status as Employee["status"]));
    }
    if (filters?.search?.trim()) {
      const pat = `%${filters.search.trim()}%`;
      conditions.push(
        or(
          ilike(employees.employeeId, pat),
          ilike(employees.position, pat),
          ilike(users.fullName, pat)
        )!
      );
    }
    const whereClause = and(...conditions);
    const [{ count: totalCount }] = await db
      .select({ count: sql`COUNT(DISTINCT ${employees.id})` })
      .from(employees)
      .innerJoin(users, eq(employees.userId, users.id))
      .where(whereClause);
    const limit = filters?.limit ?? 50;
    const offset = filters?.offset ?? 0;
    const rows = await db
      .select({ employee: employees })
      .from(employees)
      .innerJoin(users, eq(employees.userId, users.id))
      .where(whereClause)
      .orderBy(desc(employees.createdAt))
      .limit(limit)
      .offset(offset);
    return {
      data: rows.map((r: { employee: Employee }) => r.employee),
      total: Number(totalCount),
    };
  }

