  async getAttendanceRecord(id: number): Promise<AttendanceRecord | undefined> {
    const [row] = await db.select().from(attendanceRecords).where(eq(attendanceRecords.id, id));
    return row;
  }

  async createAttendanceRecord(record: InsertAttendanceRecord): Promise<AttendanceRecord> {
    let hoursWorked = record.hoursWorked ?? null;
    if (record.checkIn && record.checkOut) {
      const ms = new Date(record.checkOut).getTime() - new Date(record.checkIn).getTime();
      if (!Number.isFinite(ms) || ms <= 0) {
        throw new Error("Attendance check-out must be after check-in");
      }
      hoursWorked = (ms / (1000 * 60 * 60)).toFixed(2);
    }
    const [row] = await db
      .insert(attendanceRecords)
      .values({ ...record, hoursWorked: hoursWorked ?? record.hoursWorked ?? null })
      .returning();
    if (!row) throw new Error("Failed to create attendance record");
    return row;
  }

  async updateAttendanceRecord(
    id: number,
    updates: Partial<InsertAttendanceRecord>
  ): Promise<AttendanceRecord> {
    const [existing] = await db.select().from(attendanceRecords).where(eq(attendanceRecords.id, id));
    if (!existing) throw new Error("Attendance record not found");
    const next: Partial<InsertAttendanceRecord> = { ...updates };
    delete (next as { companyId?: number }).companyId;
    const checkIn =
      next.checkIn !== undefined ? next.checkIn : existing.checkIn;
    const checkOut =
      next.checkOut !== undefined ? next.checkOut : existing.checkOut;
    if (checkIn && checkOut) {
      const ms = new Date(checkOut).getTime() - new Date(checkIn).getTime();
      if (!Number.isFinite(ms) || ms <= 0) {
        throw new Error("Attendance check-out must be after check-in");
      }
      next.hoursWorked = (ms / (1000 * 60 * 60)).toFixed(2);
    }
    const [row] = await db
      .update(attendanceRecords)
      .set(next)
      .where(eq(attendanceRecords.id, id))
      .returning();
    if (!row) throw new Error("Attendance record not found");
    return row;
  }

  async deleteAttendanceRecord(id: number): Promise<boolean> {
    const result = await db.delete(attendanceRecords).where(eq(attendanceRecords.id, id)).returning({ id: attendanceRecords.id });
    return result.length > 0;
  }

